script:
frappe.ui.form.on('Job Opening', {
    custom_recruitment: function(frm) {
        let recruitment = frm.doc.custom_recruitment ? frm.doc.custom_recruitment.trim() : "";

        if (recruitment === 'Internal') {
            frm.set_df_property('custom_hiring_organization', 'hidden', 1);
            frm.set_df_property('section_break_nngy', 'hidden', 0);
        } else if (recruitment === 'Placement') {
            frm.set_df_property('custom_hiring_organization', 'hidden', 0);
            frm.set_df_property('section_break_nngy', 'hidden', 1);
        } else {
            // If custom_recruitment is null, empty, or not selected, hide both fields
            frm.set_df_property('custom_hiring_organization', 'hidden', 1);
            frm.set_df_property('section_break_nngy', 'hidden', 1);
        }
    },

    refresh: function(frm) {
        frm.trigger('custom_recruitment'); // Ensure script runs when form loads
    }
});



frappe.ui.form.on('Job Opening', {
    setup: function(frm) {
        frm.set_query('custom_company_name', function() {
            return {
                filters: {
                    customer_type: 'Placement'
                }
            };
        });
    }
});

frappe.ui.form.on('Job Applicant', {
    job_title: function(frm) {
        if (frm.doc.job_title) {
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Job Opening',
                    filters: { name: frm.doc.job_title },
                    fieldname: 'custom_recruitment'
                },
                callback: function(r) {
                    if (r.message && r.message.custom_recruitment) {
                        frm.set_value('custom_recruitment', r.message.custom_recruitment);
                        toggle_custom_student(frm, r.message.custom_recruitment);
                    }
                }
            });
        }
    },

    refresh: function(frm) {
        if (frm.doc.job_title && !frm.doc.custom_recruitment) {
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Job Opening',
                    filters: { name: frm.doc.job_title },
                    fieldname: 'custom_recruitment'
                },
                callback: function(r) {
                    if (r.message && r.message.custom_recruitment) {
                        frm.set_value('custom_recruitment', r.message.custom_recruitment);
                        toggle_custom_student(frm, r.message.custom_recruitment);
                    }
                }
            });
        } else {
            toggle_custom_student(frm, frm.doc.custom_recruitment);
        }
    },

    custom_recruitment: function(frm) {
        toggle_custom_student(frm, frm.doc.custom_recruitment);
    }
});

// Function to toggle visibility of 'custom_student_' field
function toggle_custom_student(frm, recruitment_type) {
    frm.toggle_display('custom_student_', recruitment_type !== 'Internal');
        frm.toggle_display('custom_hiring_company', recruitment_type !== 'Internal');

}

frappe.ui.form.on('Interview', {
    onload: function(frm) {
        fetch_student_name(frm);
    },
    refresh: function(frm) {
        fetch_student_name(frm);
    },
    job_applicant: function(frm) {
        fetch_student_name(frm);
    }
});

function fetch_student_name(frm) {
    if (frm.doc.job_applicant) {
        frappe.call({
            method: 'frappe.client.get_value',
            args: {
                doctype: 'Job Applicant',
                filters: { email_id: frm.doc.job_applicant }, // Matching email
                fieldname: 'custom_student_' // Fetching student name field
            },
            callback: function(r) {
                if (r.message && r.message.custom_student_) {
                    frm.set_value('custom_student_name', r.message.custom_student_);
                }
            }
        });
    }
}

frappe.ui.form.on('Interview', {
    job_applicant: function(frm) {
        if (frm.doc.job_applicant) {
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Job Applicant',
                    filters: { name: frm.doc.job_applicant },
                    fieldname: ['custom_recruitment', 'custom_student_']
                },
                callback: function(r) {
                    if (r.message) {
                        if (r.message.custom_recruitment) {
                            frm.set_value('custom_recruitment', r.message.custom_recruitment);
                            toggle_custom_student_name(frm, r.message.custom_recruitment);
                        }
                        if (r.message.custom_student_) {
                            frm.set_value('custom_student_name', r.message.custom_student_);
                        }
                    }
                }
            });
        }
    },

    refresh: function(frm) {
        if (frm.doc.job_applicant) {
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Job Applicant',
                    filters: { name: frm.doc.job_applicant },
                    fieldname: ['custom_recruitment', 'custom_student_']
                },
                callback: function(r) {
                    if (r.message) {
                        if (r.message.custom_recruitment) {
                            frm.set_value('custom_recruitment', r.message.custom_recruitment);
                            toggle_custom_student_name(frm, r.message.custom_recruitment);
                        }
                        if (r.message.custom_student_) {
                            frm.set_value('custom_student_name', r.message.custom_student_);
                        }
                    }
                }
            });
        }
    },

    custom_recruitment: function(frm) {
        toggle_custom_student_name(frm, frm.doc.custom_recruitment);
    }
});

// Function to toggle visibility of 'custom_student_name' field
function toggle_custom_student_name(frm, recruitment_type) {
    frm.toggle_display('custom_student_name', recruitment_type !== 'Internal');
}

frappe.ui.form.on('Interview', {
    refresh: function(frm) {
        // Call the function when the form loads
        toggle_interview_details(frm);
    },
    custom_recruitment: function(frm) {
        // Call the function when the custom_recruitment field changes
        toggle_interview_details(frm);
    }
});

function toggle_interview_details(frm) {
    if (frm.doc.custom_recruitment === 'Placement') {
        frm.set_df_property('interview_details', 'hidden', 1);
    } else {
        frm.set_df_property('interview_details', 'hidden', 0);
    }
}

frappe.ui.form.on('Job Applicant', {
    refresh: function(frm) {
        // First clear out buttons to avoid duplicates
        frm.clear_custom_buttons();

        if (frm.doc.custom_recruitment === "Placement") {
            // Hide the default Job Offer button
            frm.remove_custom_button(__('Job Offer'), __('Create'));

            // Check if a Placement already exists for this Job Applicant
            frappe.db.get_value("Placements", { job_applicant_id: frm.doc.name }, "name")
                .then(r => {
                    if (r && r.message && r.message.name) {
                        // Placement exists → Show "View Placement"
                        frm.add_custom_button(__('View Placement'), function() {
                            frappe.set_route("Form", "Placements", r.message.name);
                        }, __('Create'));
                    } else if (frm.doc.status === "Accepted") {
                        // No Placement → Show "Create Placement"
                        frm.add_custom_button(__('Create Placement'), function() {
                            frappe.new_doc('Placements', {
                                student_name: frm.doc.custom_student_,         // Link to Student
                                job_applicant_id: frm.doc.name,               // Job Applicant reference
                                placed_company: frm.doc.custom_hiring_company  // Hiring company
                            });
                        }, __('Create'));
                    }
                });

        } else {
            // If recruitment is not "Placement" → show Job Offer (default)
            frm.add_custom_button(__('Job Offer'), function() {
                frappe.new_doc('Job Offer', {
                    job_applicant: frm.doc.name,
                    applicant_name: frm.doc.applicant_name,
                    status: 'Draft'
                });
            }, __('Create'));
        }
    }
});

frappe.ui.form.on('Customer', {
    refresh: function(frm) {
        toggle_defaults_tab(frm);
    },
    customer_type: function(frm) {
        toggle_defaults_tab(frm);
    }
});

function toggle_defaults_tab(frm) {
    if (frm.doc.customer_type === 'Placement') {
        // Hide specific sections and fields
        frm.toggle_display('defaults_tab', false);
        frm.toggle_display('lead_name', false);
        frm.toggle_display('opportunity_name', false);
        frm.toggle_display('prospect_name', false);
        frm.toggle_display('internal_customer_section', false);
        frm.toggle_display('gender', false);
        frm.toggle_display('salutation', false);
        frm.toggle_display('territory', false);
        frm.toggle_display('custom_hr_name', true);
        frm.toggle_display('custom_contact_no', true);

        // Hide additional sections as requested
        frm.toggle_display('taxation_section', false);
        frm.toggle_display('tax_details_section', false);
        frm.toggle_display('payment_terms', false);
        frm.toggle_display('credit_limits', false);
        frm.toggle_display('accounts', false);
        frm.toggle_display('loyalty_points_tab', false);
        frm.toggle_display('sales_team', false);
        frm.toggle_display('sales_team_section', false);
        frm.toggle_display('column_break_53', false);
        frm.toggle_display('so_required', false);
        frm.toggle_display('dn_required', false);
        frm.toggle_display('portal_users', false);

    } else {
        // Show sections and fields if "Placement" is NOT selected
        frm.toggle_display('defaults_tab', true);
        frm.toggle_display('lead_name', true);
        frm.toggle_display('opportunity_name', true);
        frm.toggle_display('prospect_name', true);
        frm.toggle_display('internal_customer_section', true);
        frm.toggle_display('gender', true);
        frm.toggle_display('salutation', true);
        frm.toggle_display('territory', true);
        frm.toggle_display('custom_hr_name', false);
        frm.toggle_display('custom_contact_no', false);

        // Show additional sections
        frm.toggle_display('taxation_section', true);
        frm.toggle_display('tax_details_section', true);
        frm.toggle_display('payment_terms', true);
        frm.toggle_display('credit_limits', true);
        frm.toggle_display('accounts', true);
        frm.toggle_display('loyalty_points_tab', true);
        frm.toggle_display('sales_team', true);
        frm.toggle_display('sales_team_section', true);
        frm.toggle_display('column_break_53', true);
        frm.toggle_display('so_required', true);
        frm.toggle_display('dn_required', true);
        frm.toggle_display('portal_users', true);
    }
}

frappe.ui.form.on('Assessment Plan', {
    course: function (frm) {
        if (frm.doc.course === "20*9 Activity") {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Assessment Criteria",
                    filters: {
                        assessment_criteria_group: "20*9 Activity"
                    },
                    fields: ["name"]
                },
                callback: function (r) {
                    if (r.message) {
                        let criteria = r.message;
                        let total_criteria = criteria.length;

                        frm.set_value("maximum_assessment_score", total_criteria);
                        frm.clear_table("assessment_criteria");

                        criteria.forEach(function (item) {
                            let row = frm.add_child("assessment_criteria");
                            row.assessment_criteria = item.name;
                            row.maximum_score = 1.0;
                        });

                        frm.refresh_field("assessment_criteria");
                    }
                }
            });
        }
    }
});
